                "field": "Microsoft.Compute/imagePublisher",
                "notEquals": "AzureDatabricks"
              },
              {
                "anyOf": [
                  {
                    "not": {
                      "field": "[concat('tags[', parameters('exclusionTagName'), ']')]",
                      "in": "[parameters('exclusionTagValue')]"
                    }
                  },
                  {
                    "value": "[empty(parameters('exclusionTagValue'))]",
                    "equals": "true"
