                          }
                        }
                      }
                    ]
                  },
                  "parameters": {
                    "clusterLocation": {
                      "value": "[field('location')]"
                    },
                    "clusterName": {
                      "value": "[field('name')]"
                    },
                    "configurationResourceName": {
                      "value": "[parameters('configurationResourceName')]"
                    },
                    "operatorInstanceName": {
