    {
      "properties": {
        "displayName": "An activity log alert should exist for specific Security operations",
        "policyType": "BuiltIn",
        "mode": "All",
        "description": "This policy audits specific Security operations with no activity log alerts configured.",
        "metadata": {
          "version": "1.0.0",
          "category": "Monitoring"
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "AuditIfNotExists",
              "Disabled"
            ],
            "defaultValue": "AuditIfNotExists"
          },
          "operationName": {
            "type": "String",
            "metadata": {
              "displayName": "Operation Name",
              "description": "Security Operation name for which activity log alert should exist"
            },
            "allowedValues": [
              "Microsoft.Security/policies/write",
              "Microsoft.Security/securitySolutions/write",
              "Microsoft.Security/securitySolutions/delete"
            ]
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Resources/subscriptions"
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.Insights/ActivityLogAlerts",
              "existenceCondition": {
                "allOf": [
                  {
                    "field": "Microsoft.Insights/ActivityLogAlerts/enabled",
                    "equals": "true"
                  },
                  {
                    "count": {
                      "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*]",
                      "where": {
                        "anyOf": [
                          {
                            "allOf": [
                              {
                                "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].field",
                                "equals": "category"
                              },
                              {
                                "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].equals",
                                "equals": "Security"
                              }
                            ]
                          },
                          {
                            "allOf": [
                              {
                                "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].field",
                                "equals": "operationName"
                              },
                              {
                                "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].equals",
                                "equals": "[parameters('operationName')]"
                              }
                            ]
                          }
                        ]
                      }
                    },
                    "equals": 2
                  },
                  {
                    "not": {
                      "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].field",
                      "equals": "category"
                    }
                  },
                  {
                    "not": {
                      "field": "Microsoft.Insights/ActivityLogAlerts/condition.allOf[*].field",
                      "equals": "operationName"
                    }
                  }
                ]
              }
            }
          }
        }
      },
