      "id": "/providers/Microsoft.Authorization/policyDefinitions/493a95f3-f2e3-47d0-af02-65e6d6decc2f",
      "type": "Microsoft.Authorization/policyDefinitions",
      "name": "493a95f3-f2e3-47d0-af02-65e6d6decc2f"
    },
    {
      "properties": {
        "displayName": "Ensure that 'Java version' is the latest, if used as a part of the Web app",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Periodically, newer versions are released for Java software either due to security flaws or to include additional functionality. Using the latest Java version for web apps is recommended in order to take advantage of security fixes, if any, and/or new functionalities of the latest version. Currently, this policy only applies to Linux web apps.",
        "metadata": {
          "version": "2.0.0",
          "category": "App Service"
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "AuditIfNotExists",
              "Disabled"
            ],
            "defaultValue": "AuditIfNotExists"
          },
          "JavaLatestVersion": {
            "type": "String",
            "metadata": {
              "displayName": "Latest Java version",
              "description": "Latest supported Java version for App Services"
            },
            "defaultValue": "11"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Web/sites"
              },
              {
                "field": "kind",
                "like": "app*"
              },
              {
                "field": "kind",
                "contains": "linux"
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.Web/sites/config",
              "name": "web",
              "existenceCondition": {
                "anyOf": [
                  {
                    "field": "Microsoft.Web/sites/config/web.linuxFxVersion",
                    "notContains": "JAVA"
                  },
                  {
                    "field": "Microsoft.Web/sites/config/web.linuxFxVersion",
                    "like": "[concat('*', parameters('JavaLatestVersion'))]"
                  }
                ]
              }
            }
          }
        }
      },
      "id": "/providers/Microsoft.Authorization/policyDefinitions/496223c3-ad65-4ecd-878a-bae78737e9ed",
      "type": "Microsoft.Authorization/policyDefinitions",
      "name": "496223c3-ad65-4ecd-878a-bae78737e9ed"
    },
    {
      "properties": {
        "displayName": "Configure private endpoints for Data factories",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Private endpoints connect your virtual network to Azure services without a public IP address at the source or destination.  By mapping private endpoints to your Azure Data Factory, you can reduce data leakage risks.  Learn more at: https://docs.microsoft.com/azure/data-factory/data-factory-private-link.",
        "metadata": {
          "version": "1.0.0",
          "category": "Data Factory"
        },
        "parameters": {
          "privateEndpointSubnetId": {
            "type": "String",
            "metadata": {
              "displayName": "Private endpoint subnet ID",
              "description": "A subnet with private endpoint network policies disabled.",
              "strongType": "Microsoft.Network/virtualNetworks/subnets"
            }
          },
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "DeployIfNotExists",
              "Disabled"
            ],
            "defaultValue": "DeployIfNotExists"
          },
          "groupId": {
            "type": "String",
            "metadata": {
              "description": "The group Id that can be specified for Private Endpoints.",
              "displayName": "Allowed group Id"
            },
            "allowedValues": [
              "dataFactory",
              "portal"
            ],
            "defaultValue": "dataFactory"
          }
        },
        "policyRule": {
          "if": {
            "field": "type",
            "equals": "Microsoft.DataFactory/factories"
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.DataFactory/factories/privateEndpointConnections",
              "existenceCondition": {
                "field": "Microsoft.DataFactory/factories/privateEndpointConnections/privateLinkServiceConnectionState.status",
                "equals": "Approved"
              },
              "roleDefinitionIds": [
                "/providers/Microsoft.Authorization/roleDefinitions/673868aa-7521-48a0-acc6-0f60742d39f5"
              ],
              "deployment": {
                "properties": {
                  "mode": "incremental",
                  "parameters": {
                    "name": {
                      "value": "[field('name')]"
                    },
                    "serviceId": {
                      "value": "[field('id')]"
                    },
                    "privateEndpointSubnetId": {
                      "value": "[parameters('privateEndpointSubnetId')]"
                    },
                    "groupId": {
                      "value": "[parameters('groupId')]"
                    }
                  },
                  "template": {
                    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                      "name": {
                        "type": "string"
                      },
                      "serviceId": {
                        "type": "string"
                      },
                      "privateEndpointSubnetId": {
                        "type": "string"
                      },
                      "groupId": {
                        "type": "string"
                      }
                    },
                    "variables": {
                      "privateEndpointName": "[concat('pe-',substring(parameters('name'),0,min(length(parameters('name')),50)),'-',uniquestring(deployment().name))]"
                    },
                    "resources": [
                      {
                        "type": "Microsoft.Resources/deployments",
                        "name": "[variables('privateEndpointName')]",
                        "apiVersion": "2020-06-01",
                        "properties": {
                          "mode": "Incremental",
                          "expressionEvaluationOptions": {
                            "scope": "inner"
                          },
                          "template": {
                            "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
                            "contentVersion": "1.0.0.0",
                            "parameters": {
                              "serviceId": {
                                "type": "string"
                              },
                              "privateEndpointSubnetId": {
                                "type": "string"
                              },
                              "subnetLocation": {
                                "type": "string"
                              },
                              "groupId": {
                                "type": "string"
                              }
                            },
                            "variables": {
                              "privateEndpointName": "[deployment().name]"
                            },
                            "resources": [
                              {
                                "name": "[variables('privateEndpointName')]",
                                "type": "Microsoft.Network/privateEndpoints",
                                "apiVersion": "2020-07-01",
                                "location": "[parameters('subnetLocation')]",
                                "tags": {},
                                "properties": {
                                  "subnet": {
                                    "id": "[parameters('privateEndpointSubnetId')]"
                                  },
                                  "privateLinkServiceConnections": [
                                    {
                                      "name": "[variables('privateEndpointName')]",
                                      "properties": {
                                        "privateLinkServiceId": "[parameters('serviceId')]",
                                        "groupId": [
                                          "[parameters('groupId')]"
                                        ],
                                        "requestMessage": "autoapprove"
                                      }
                                    }
                                  ],
                                  "manualPrivateLinkServiceConnections": []
                                }
                              }
                            ]
                          },
                          "parameters": {
                            "serviceId": {
                              "value": "[parameters('serviceId')]"
                            },
                            "privateEndpointSubnetId": {
                              "value": "[parameters('privateEndpointSubnetId')]"
                            },
                            "subnetLocation": {
                              "value": "[reference(first(take(split(parameters('privateEndpointSubnetId'),'/subnets'),1)),'2020-07-01','Full').location]"
                            },
                            "groupId": {
                              "value": "[parameters('groupId')]"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          }
        }
      },
      "id": "/providers/Microsoft.Authorization/policyDefinitions/496ca26b-f669-4322-a1ad-06b7b5e41882",
      "type": "Microsoft.Authorization/policyDefinitions",
      "name": "496ca26b-f669-4322-a1ad-06b7b5e41882"
    },
    {
      "properties": {
        "displayName": "[Preview]: Configure VMs created with Shared Image Gallery images to install the Guest Attestation extension",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Configure virtual machines created with Shared Image Gallery images to automatically install the Guest Attestation extension to allow Azure Security Center to proactively attest and monitor the boot integrity. Boot integrity is attested via Remote Attestation.",
        "metadata": {
          "category": "Security Center",
          "version": "2.0.0-preview",
          "preview": true
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "DeployIfNotExists",
              "Disabled"
            ],
            "defaultValue": "DeployIfNotExists"
          },
          "attestationEndpoint": {
            "type": "String",
            "metadata": {
              "displayName": "Guest attestation tenant URL",
              "description": "The Microsoft Azure Attestation (MAA) custom tenant URL."
            },
            "defaultValue": ""
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Compute/virtualMachines"
              },
              {
                "field": "Microsoft.Compute/virtualMachines/securityProfile.securityType",
                "equals": "TrustedLaunch"
              },
              {
                "field": "Microsoft.Compute/virtualMachines/securityProfile.uefiSettings",
                "exists": "true"
              },
              {
                "field": "Microsoft.Compute/virtualMachines/securityProfile.uefiSettings.vTpmEnabled",
                "equals": "true"
              },
              {
                "field": "Microsoft.Compute/virtualMachines/securityProfile.uefiSettings.secureBootEnabled",
                "equals": "true"
              },
              {
                "field": "Microsoft.Compute/imageid",
                "exists": "true"
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.Compute/virtualMachines/extensions",
              "existenceCondition": {
                "allOf": [
                  {
                    "field": "Microsoft.Compute/virtualMachines/extensions/publisher",
                    "in": [
                      "Microsoft.Azure.Security.LinuxAttestation",
                      "Microsoft.Azure.Security.WindowsAttestation"
                    ]
                  },
                  {
                    "field": "Microsoft.Compute/virtualMachines/extensions/type",
                    "equals": "GuestAttestation"
                  },
                  {
                    "field": "Microsoft.Compute/virtualMachines/extensions/provisioningState",
                    "in": [
                      "Succeeded",
                      "Provisioning succeeded"
                    ]
                  }
                ]
              },
              "roleDefinitionIds": [
                "/providers/microsoft.authorization/roleDefinitions/acdd72a7-3385-48ef-bd42-f606fba81ae7",
                "/providers/microsoft.authorization/roleDefinitions/9980e02c-c2be-4d73-94e8-173b1dc7cf3c"
              ],
              "deployment": {
                "properties": {
                  "mode": "incremental",
                  "parameters": {
                    "vmName": {
                      "value": "[field('name')]"
                    },
                    "location": {
                      "value": "[field('location')]"
                    },
                    "imageId": {
                      "value": "[field('Microsoft.Compute/imageid')]"
                    },
                    "attestationEndpoint": {
                      "value": "[parameters('attestationEndpoint')]"
                    }
                  },
                  "template": {
                    "$schema": "http://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                      "vmName": {
                        "type": "string"
                      },
                      "location": {
                        "type": "string"
                      },
                      "imageId": {
                        "type": "string"
                      },
                      "attestationEndpoint": {
                        "type": "string"
                      }
                    },
                    "variables": {
                      "extensionName": "GuestAttestation",
                      "extensionPublisherPrefix": "Microsoft.Azure.Security.",
                      "extensionPublisherSuffix": "Attestation",
                      "extensionVersion": "1.0",
                      "maaTenantName": "GuestAttestation",
                      "ascReportingEndpoint": ""
                    },
                    "resources": [
                      {
                        "type": "Microsoft.Compute/virtualMachines/extensions",
                        "apiVersion": "2018-10-01",
                        "name": "[concat(parameters('vmName'), '/', variables('extensionName'))]",
                        "location": "[parameters('location')]",
                        "properties": {
                          "publisher": "[concat(variables('extensionPublisherPrefix'), reference(split(parameters('imageId'), '/versions')[0], '2021-07-01').osType, variables('extensionPublisherSuffix'))]",
                          "type": "[variables('extensionName')]",
                          "typeHandlerVersion": "[variables('extensionVersion')]",
                          "autoUpgradeMinorVersion": true,
                          "settings": {
                            "AttestationConfig": {
                              "MaaSettings": {
                                "maaEndpoint": "[parameters('attestationEndpoint')]",
                                "maaTenantName": "[variables('maaTenantName')]"
                              },
                              "AscSettings": {
                                "ascReportingEndpoint": "[variables('ascReportingEndpoint')]",
                                "ascReportingFrequency": ""
                              },
                              "useCustomToken": "false",
                              "disableAlerts": "false"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          }
        }
      },
      "id": "/providers/Microsoft.Authorization/policyDefinitions/496e010e-fa91-4c00-be4b-92b481f67b58",
      "type": "Microsoft.Authorization/policyDefinitions",
      "name": "496e010e-fa91-4c00-be4b-92b481f67b58"
    },
    {
      "properties": {
        "displayName": "Add system-assigned managed identity to enable Guest Configuration assignments on VMs with a user-assigned identity",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "This policy adds a system-assigned managed identity to virtual machines hosted in Azure that are supported by Guest Configuration and have at least one user-assigned identity but do not have a system-assigned managed identity. A system-assigned managed identity is a prerequisite for all Guest Configuration assignments and must be added to machines before using any Guest Configuration policy definitions. For more information on Guest Configuration, visit https://aka.ms/gcpol.",
        "metadata": {
          "category": "Guest Configuration",
          "version": "1.0.0"
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Compute/virtualMachines"
              },
              {
                "anyOf": [
                  {
