                                "dependsOn": [],
                                "properties": {
                                  "description": "Workflow Automation for Azure Security Center recommendations via policy",
                                  "isEnabled": true,
                                  "scopes": [
                                    {
                                      "description": "[replace(variables('scopeDescription'),'{0}', subscription().subscriptionId)]",
                                      "scopePath": "[subscription().id]"
                                    }
                                  ],
                                  "sources": [
