              },
              {
                "anyOf": [
                  {
                    "field": "Microsoft.MachineLearningServices/workspaces/primaryUserAssignedIdentity",
                    "exists": false
                  },
                  {
                    "field": "Microsoft.MachineLearningServices/workspaces/primaryUserAssignedIdentity",
                    "equals": ""
                  }
                ]
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]"
          }
        }
