                        "apiVersion": "2017-05-01-preview",
                        "name": "[concat(parameters('resourceName'), '/default/', 'Microsoft.Insights/', parameters('diagnosticsSettingNameToUse'))]",
                        "location": "[parameters('location')]",
                        "dependsOn": [],
