    {
      "properties": {
        "displayName": "Configure Linux Arc machines to run Azure Monitor Agent",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Automate the deployment of Azure Monitor Agent extension on your Linux Arc machines for collecting telemetry data from the guest OS. This policy will install the extension if the region is supported. Learn more: https://aka.ms/AMAOverview.",
        "metadata": {
          "version": "1.0.0",
          "category": "Monitoring"
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy."
            },
            "allowedValues": [
              "DeployIfNotExists",
              "Disabled"
            ],
            "defaultValue": "DeployIfNotExists"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.HybridCompute/machines"
              },
              {
                "field": "Microsoft.HybridCompute/machines/osName",
                "equals": "linux"
              },
              {
                "field": "location",
                "in": [
                  "australiacentral",
                  "australiaeast",
                  "australiasoutheast",
                  "brazilsouth",
                  "canadacentral",
                  "canadaeast",
                  "centralindia",
                  "centralus",
                  "eastasia",
                  "eastus2euap",
                  "eastus",
                  "eastus2",
                  "francecentral",
                  "germanywestcentral",
                  "japaneast",
                  "japanwest",
                  "jioindiawest",
                  "koreacentral",
                  "koreasouth",
                  "northcentralus",
                  "northeurope",
                  "norwayeast",
                  "southafricanorth",
                  "southcentralus",
                  "southeastasia",
                  "southindia",
                  "switzerlandnorth",
                  "uaenorth",
                  "uksouth",
                  "ukwest",
                  "westcentralus",
                  "westeurope",
                  "westindia",
                  "westus",
                  "westus2"
                ]
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.HybridCompute/machines/extensions",
              "roleDefinitionIds": [
                "/providers/Microsoft.Authorization/roleDefinitions/92aaf0da-9dab-42b6-94a3-d43ce8d16293"
              ],
              "existenceCondition": {
                "allOf": [
                  {
                    "field": "Microsoft.HybridCompute/machines/extensions/type",
                    "equals": "AzureMonitorLinuxAgent"
                  },
                  {
                    "field": "Microsoft.HybridCompute/machines/extensions/publisher",
                    "equals": "Microsoft.Azure.Monitor"
                  },
                  {
                    "field": "Microsoft.HybridCompute/machines/extensions/provisioningState",
                    "equals": "Succeeded"
                  }
                ]
              },
              "deployment": {
                "properties": {
                  "mode": "incremental",
                  "template": {
                    "$schema": "https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                      "vmName": {
                        "type": "string"
                      },
                      "location": {
                        "type": "string"
                      }
                    },
                    "variables": {
                      "extensionName": "AzureMonitorLinuxAgent",
                      "extensionPublisher": "Microsoft.Azure.Monitor",
                      "extensionType": "AzureMonitorLinuxAgent",
                      "extensionTypeHandlerVersion": "1.12"
                    },
                    "resources": [
                      {
                        "name": "[concat(parameters('vmName'), '/', variables('extensionName'))]",
                        "type": "Microsoft.HybridCompute/machines/extensions",
                        "location": "[parameters('location')]",
                        "apiVersion": "2021-05-20",
                        "properties": {
                          "publisher": "[variables('extensionPublisher')]",
                          "type": "[variables('extensionType')]",
                          "typeHandlerVersion": "[variables('extensionTypeHandlerVersion')]",
                          "autoUpgradeMinorVersion": true
                        }
                      }
                    ]
                  },
                  "parameters": {
                    "vmName": {
                      "value": "[field('name')]"
                    },
                    "location": {
                      "value": "[field('location')]"
                    }
                  }
                }
              }
            }
          }
        }
      },
