    {
      "properties": {
        "displayName": "[Preview]: Configure machines to automatically create the Azure Security Center pipeline for Azure Monitor Agent",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Configure machines to automatically create the Azure Security Center pipeline for Azure Monitor Agent. Security Center collects events from the agent and uses them to provide security alerts and tailored hardening tasks (recommendations). Create a resource group and Log Analytics workspace in the same region as the machine to store audit records. Target virtual machines must be in a supported location.",
        "metadata": {
          "category": "Security Center",
          "version": "4.0.0-preview",
          "preview": true
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "DeployIfNotExists",
              "Disabled"
            ],
            "defaultValue": "DeployIfNotExists"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Compute/virtualMachines"
              },
              {
                "field": "location",
                "in": [
                  "australiacentral",
                  "australiaeast",
                  "australiasoutheast",
                  "canadacentral",
                  "centralindia",
                  "centralus",
                  "eastasia",
                  "eastus2euap",
                  "eastus",
                  "eastus2",
                  "francecentral",
                  "germanywestcentral",
                  "japaneast",
                  "koreacentral",
                  "northcentralus",
                  "northeurope",
                  "southafricanorth",
                  "southcentralus",
                  "southeastasia",
                  "switzerlandnorth",
                  "uksouth",
                  "ukwest",
                  "westcentralus",
                  "westeurope",
                  "westus",
                  "westus2"
                ]
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "type": "Microsoft.Insights/dataCollectionRules",
              "deploymentScope": "subscription",
              "roleDefinitionIds": [
                "/providers/microsoft.authorization/roleDefinitions/b24988ac-6180-42a0-ab88-20f7382dd24c"
              ],
              "existenceScope": "subscription",
              "existenceCondition": {
                "allOf": [
                  {
                    "field": "location",
                    "equals": "[field('location')]"
                  },
                  {
                    "field": "name",
                    "equals": "[concat('Microsoft-Security-', field('location'), '-dcr')]"
                  }
                ]
              },
              "deployment": {
                "location": "eastus",
                "properties": {
                  "mode": "incremental",
                  "parameters": {
                    "resourceGroup": {
                      "value": "[resourceGroup().name]"
                    },
                    "location": {
                      "value": "[field('location')]"
                    },
                    "vmName": {
                      "value": "[field('name')]"
                    }
                  },
                  "template": {
                    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                      "resourceGroup": {
                        "type": "string"
                      },
                      "location": {
                        "type": "string"
                      },
                      "vmName": {
                        "type": "string"
                      }
                    },
                    "variables": {
                      "locationLongNameToShortMap": {
                        "australiacentral": "CAU",
                        "australiaeast": "EAU",
                        "australiasoutheast": "SEAU",
                        "brazilsouth": "CQ",
                        "canadacentral": "CCA",
                        "centralindia": "CIN",
                        "centralus": "CUS",
                        "eastasia": "EA",
