            "Microsoft.GuestConfiguration"
          ],
          "guestConfiguration": {
            "name": "WindowsCertificateInTrustedRoot",
            "version": "1.*",
            "configurationParameter": {
              "CertificateThumbprints": "[CertificateStore]CertificateStore1;CertificateThumbprintsToInclude"
            }
          }
        },
        "parameters": {
          "IncludeArcMachines": {
            "type": "String",
