            },
            "allowedValues": [
              "Audit",
              "Deny",
              "Disabled"
            ],
            "defaultValue": "Audit"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.Batch/batchAccounts"
              },
              {
                "field": "Microsoft.Batch/batchAccounts/encryption.keySource",
                "notEquals": "Microsoft.KeyVault"
              }
            ]
          },
          "then": {
            "effect": "[parameters('effect')]"
          }
        }
      },
