        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "To ensure the operations performed against your SQL assets are captured, Synapse workspaces should have auditing enabled. This is sometimes required for compliance with regulatory standards.",
        "metadata": {
          "version": "2.0.0",
          "category": "Synapse"
        },
        "parameters": {
          "effect": {
            "type": "String",
