      "name": "f08f556c-12ff-464d-a7de-40cb5b6cccec"
    },
    {
      "properties": {
        "displayName": "Latest TLS version should be used in your Web App",
        "policyType": "BuiltIn",
        "mode": "Indexed",
        "description": "Upgrade to the latest TLS version",
        "metadata": {
          "version": "1.0.0",
          "category": "App Service"
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "Enable or disable the execution of the policy"
            },
            "allowedValues": [
              "AuditIfNotExists",
