            ],
            "defaultValue": "Audit"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.KeyVault.Data/vaults/keys"
              },
              {
                "field": "Microsoft.KeyVault.Data/vaults/keys/attributes.expiresOn",
                "exists": true
              },
              {
                "field": "Microsoft.KeyVault.Data/vaults/keys/attributes.expiresOn",
