            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.KeyVault.Data/vaults/secrets"
              },
              {
                "field": "Microsoft.KeyVault.Data/vaults/secrets/attributes.expiresOn",
                "exists": false
              }
            ]
          },
          "then": {
