            "allowedValues": [
              "audit",
              "deny",
              "disabled"
            ],
            "defaultValue": "audit"
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "equals": "Microsoft.KeyVault.Data/vaults/certificates"
              },
              {
                "field": "Microsoft.KeyVault.Data/vaults/certificates/keyProperties.keyType",
                "in": [
                  "RSA",
