      "properties": {
        "displayName": "[E2E Custom Policy Test] Kubernetes cluster pod hostPath volumes should only use allowed host paths",
        "policyType": "Custom",
        "mode": "Microsoft.Kubernetes.Data",
        "metadata": {
          "createdBy": "3df87bed-2f50-425e-b89b-e3b9be739a42",
          "createdOn": "2021-09-13T02:42:16.2950103Z",
          "updatedBy": null,
          "updatedOn": null
        },
        "parameters": {
          "effect": {
            "type": "String",
            "metadata": {
              "displayName": "Effect",
              "description": "'Audit' allows a non-compliant resource to be created or updated, but flags it as non-compliant. 'Deny' blocks the non-compliant resource creation or update. 'Disabled' turns off the policy."
            },
            "allowedValues": [
              "audit",
              "deny",
              "disabled"
            ],
            "defaultValue": "audit"
          },
          "excludedNamespaces": {
            "type": "Array",
            "metadata": {
              "displayName": "Namespace exclusions",
              "description": "List of Kubernetes namespaces to exclude from policy evaluation."
            },
            "defaultValue": []
          },
          "namespaces": {
            "type": "Array",
            "metadata": {
              "displayName": "Namespace inclusions",
              "description": "List of Kubernetes namespaces to only include in policy evaluation. An empty list means the policy is applied to all resources in all namespaces."
            },
            "defaultValue": []
          },
          "allowedHostPaths": {
            "type": "Object",
            "metadata": {
              "displayName": "Allowed host paths",
              "description": "The host paths allowed for pod hostPath volumes to use. Provide an empty paths list to block all host paths."
            },
            "defaultValue": {
              "paths": []
            }
          }
        },
        "policyRule": {
          "if": {
            "field": "type",
            "in": [
              "AKS Engine",
              "Microsoft.Kubernetes/connectedClusters",
              "Microsoft.ContainerService/managedClusters"
            ]
          },
          "then": {
            "effect": "[parameters('effect')]",
            "details": {
              "constraintTemplate": "AllowedHostPaths",
              "templateInfo": {
                "sourceType": "PublicURL",
                "url": "https://store.policy-df.core.windows.net/kubernetes/allowed-host-paths-e2e-int/v1/template.yaml"
              },
              "excludedNamespaces": "[parameters('excludedNamespaces')]",
              "namespaces": "[parameters('namespaces')]",
              "apiGroups": [
                ""
              ],
              "kinds": [
                "Pod"
              ],
              "values": {
                "allowedHostPaths": "[parameters('allowedHostPaths').paths]"
              }
            }
          }
        }
      },
