    },
    {
      "properties": {
        "displayName": "Deny WVD resource creation unless Tagged",
        "policyType": "Custom",
        "mode": "All",
        "description": "IAMAADENG@microsoft.com",
        "metadata": {
          "createdBy": "7f1579a6-c648-43a1-ac1e-0c3020dd9b8e",
          "createdOn": "2021-03-04T20:07:21.852096Z",
          "updatedBy": null,
          "updatedOn": null
        },
        "parameters": {
          "allowedTag": {
            "type": "String",
            "metadata": {
              "displayName": "Allowed Tag Value",
              "description": "The tag value which allows WVD resource creation."
            }
          }
        },
        "policyRule": {
          "if": {
            "allOf": [
              {
                "field": "type",
                "like": "Microsoft.DesktopVirtualization/*"
              },
              {
                "value": "[field('type')]",
                "like": "Microsoft.DesktopVirtualization/*"
              },
              {
                "value": "[contains(subscription().tags, parameters('allowedTag'))]",
                "equals": "false"
              },
              {
                "value": "[contains(resourceGroup().tags, parameters('allowedTag'))]",
                "equals": "false"
              },
              {
                "field": "[concat('tags[', parameters('allowedTag'), ']')]",
                "exists": "false"
              }
            ]
          },
          "then": {
            "effect": "deny"
          }
        }
      },
      "id": "/providers/Microsoft.Management/managementGroups/72f988bf-86f1-41af-91ab-2d7cd011db47/providers/Microsoft.Authorization/policyDefinitions/Deny WVD creation unless Tagged",
      "type": "Microsoft.Authorization/policyDefinitions",
      "name": "Deny WVD creation unless Tagged"
    },
